/**
 * Extends the customer account statement controller to populate the
 * customer transaction description for sales invoices and sales credit notes.
 *
 * The description is determined using the customer's industry key and the
 * configured customer statement description setup. For sales invoices,
 * the method falls back to the MET OSC code when no configured description
 * is available or when an industry key is not found.
 */
protected void populateCustAccountStatementExtTmp(int _custCurrencyIndex)
{
    next populateCustAccountStatementExtTmp(_custCurrencyIndex);

    if (cust_Trans && currentTrans.Invoice && currentTrans.TransType ==LedgerTransType::Sales)
    {
        this.metSetSalesOrderDescription();
    }
}

/// <summary>
/// Sets CustTrans_Txt for the current sales order transaction.
/// Leaves the standard value untouched when nothing resolves.
/// </summary>
private void metSetSalesOrderDescription()
{
    SalesTable salesTable = METCustActivityStatementController::findSalesTableFromCustTrans(currentTrans.AccountNum,
                                                                                            currentTrans.Voucher,
                                                                                            currentTrans.Invoice,
                                                                                            currentTrans.TransDate);

    if (!salesTable.SalesId)
    {
        return;
    }

    boolean                 isCreditNote    = this.metIsCreditNote(salesTable);
    METCustStmtTransType    stmtTransType   = isCreditNote ? METCustStmtTransType::SalesCreditNote : METCustStmtTransType::SalesInvoice;
    METCustStmtIndustryKey  industryKey     = METCustActivityStatementController::getIndustryKey(salesTable.SalesId);

    // 1. Form notes setup for the industry key.
    str description = industryKey ? METCustStmtDescriptionSetup::find(stmtTransType, industryKey).DefaultDescription : '';

    // 2. Invoices only: OSC code of the first sales order line on this invoice.
    if (!description && !isCreditNote)
    {
        SalesLine salesLine     = SalesLine::find(salesTable.SalesId);
        description             = salesLine.displayMETOSCCode();
    }

    // 3. Charge-through orders.
    if (!description && this.metIsChargeThrough(salesTable))
    {
        description = isCreditNote ? "@MET:METCustStmtCrDirectCharge" : "@MET:METCustStmtDirectCharge";
    }

    if (description)
    {
        custAccountStatementExtTmp.CustTrans_Txt = description;
    }
}

/// <summary>
/// Credit note = negative transaction or return order.
/// </summary>
private boolean metIsCreditNote(SalesTable _salesTable)
{
    return currentTrans.AmountCur < 0
        || _salesTable.SalesType == SalesType::ReturnItem;
}

/// <summary>
/// True if the sales order is a charge-through order.
/// </summary>
private boolean metIsChargeThrough(SalesTable _salesTable)
{
    // Compares against the value stored in METSalesOrderType (see note).
    return _salesTable.METSalesOrderType == '@MET:METChargeThrough';
}
